const body = $input.first().json.body;
const required = ['prospect_name', 'prospect_company', 'sender_name', 'value_proposition', 'email_goal'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const goalTypes = ['book_meeting', 'get_reply', 'share_resource', 'partnership', 'sales_intro', 'investor_intro', 'job_inquiry', 'other'];
const emailGoal = goalTypes.includes(body.email_goal) ? body.email_goal : 'get_reply';
const tones = ['direct', 'warm', 'formal', 'casual', 'challenger'];
const tone = tones.includes(body.tone) ? body.tone : 'direct';
return [{ json: {
  valid: true,
  prospectName: body.prospect_name.trim(),
  prospectTitle: body.prospect_title || '',
  prospectCompany: body.prospect_company.trim(),
  prospectLinkedIn: body.prospect_linkedin_url || '',
  prospectContext: (body.prospect_context || '').slice(0, 600),
  senderName: body.sender_name.trim(),
  senderTitle: body.sender_title || '',
  senderCompany: body.sender_company || '',
  valueProposition: body.value_proposition.trim().slice(0, 500),
  socialProof: (body.social_proof || '').slice(0, 300),
  emailGoal,
  tone,
  cta: body.cta || '',
  wordLimit: Math.min(200, Math.max(50, parseInt(body.word_limit) || 100)),
  avoidPhrases: Array.isArray(body.avoid_phrases) ? body.avoid_phrases : (body.avoid_phrases || '').split(',').map(p => p.trim()).filter(Boolean),
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

const searchResults = $input.first().json?.results || [];
const input = $('Validate Input').first().json;
const webContext = searchResults.map(r => `${r.title}: ${(r.content||r.snippet||'').slice(0,300)}`).join('\n');
const combinedContext = [input.prospectContext, webContext].filter(Boolean).join('\n\n');
return [{ json: { input, prospectResearch: combinedContext || 'No research available.' } }];

values.content:
Write a personalized cold email.

Prospect: {{ $json.input.prospectName }}{{ $json.input.prospectTitle ? ', ' + $json.input.prospectTitle : '' }} at {{ $json.input.prospectCompany }}
Sender: {{ $json.input.senderName }}{{ $json.input.senderTitle ? ', ' + $json.input.senderTitle : '' }}{{ $json.input.senderCompany ? ' at ' + $json.input.senderCompany : '' }}
Goal: {{ $json.input.emailGoal.replace(/_/g,' ') }}
Tone: {{ $json.input.tone }}
Word limit: {{ $json.input.wordLimit }}
Value prop: {{ $json.input.valueProposition }}
Social proof: {{ $json.input.socialProof || 'none provided' }}
CTA preference: {{ $json.input.cta || 'suggest appropriate CTA' }}
Avoid phrases: {{ $json.input.avoidPhrases.join(', ') || 'none specified' }}

Prospect research:
{{ $json.prospectResearch }}

Return this JSON:
{
  "subject_line": "subject line — specific, not generic, ideally under 8 words",
  "subject_alternatives": ["2 alternative subject lines with different angles"],
  "personalization_hook": "the specific thing from the research used to open the email — or null if no good hook found",
  "email_body": "complete email body — under the word limit, in the requested tone. No greeting like 'Hi [name]' — start with the hook or first sentence directly. End with the CTA.",
  "email_with_greeting": "full email including 'Hi [ProspectName],' opener and sign-off with sender name",
  "cta_used": "the specific CTA in this email",
  "word_count": 0,
  "personalization_quality": "one of: highly_personalized | moderately_personalized | generic_industry | could_not_personalize",
  "personalization_quality_note": "why this rating — what was or wasn't available to personalize with",
  "what_to_research_before_sending": ["specific things to look up per prospect before hitting send — not generic but based on this particular situation"],
  "follow_up_angle": "a different angle for the follow-up email if this one doesn't get a reply"
}

