const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let email;
try { email = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
email._meta = { prospectName: input.prospectName, prospectCompany: input.prospectCompany, senderName: input.senderName, emailGoal: input.emailGoal, tone: input.tone, replyEmail: input.replyEmail };
return [{ json: email }];

const e = $input.first().json;
const m = e._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const pqColors = { highly_personalized:'#16a34a', moderately_personalized:'#2563eb', generic_industry:'#d97706', could_not_personalize:'#dc2626' };
const pqColor = pqColors[e.personalization_quality] || '#6b7280';

const altSubjects = (e.subject_alternatives||[]).map((s,i) => `<div style="font-size:13px;padding:6px 0;border-bottom:1px solid #f3f4f6;color:#6b7280">${i+2}. ${esc(s)}</div>`).join('');
const researchItems = (e.what_to_research_before_sending||[]).map(r => `<li style="font-size:13px;margin-bottom:6px;line-height:1.5;color:#374151">${esc(r)}</li>`).join('');

const emailBodyHtml = esc(e.email_with_greeting || e.email_body || '').replace(/\n/g,'<br>');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:680px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:4px">Cold Email · ${esc(m.emailGoal.replace(/_/g,' '))} · ${esc(m.tone)}</div>
    <div style="font-size:18px;font-weight:700">To: ${esc(m.prospectName)} at ${esc(m.prospectCompany)}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:3px">From: ${esc(m.senderName)} · ${e.word_count||'?'} words · <span style="color:${pqColor}">${esc((e.personalization_quality||'').replace(/_/g,' '))}</span></div>
  </div>

  <div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:4px">Subject line</div>
    <div style="font-size:17px;font-weight:700;color:#1a1a1a;margin-bottom:8px">${esc(e.subject_line)}</div>
    ${altSubjects}
  </div>

  ${e.personalization_hook ? `<div style="background:#eff6ff;padding:12px 26px;border:1px solid #bfdbfe">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:4px">Personalization hook used</div>
    <div style="font-size:13px;color:#1e40af">${esc(e.personalization_hook)}</div>
  </div>` : ''}

  <div style="background:#fff;padding:18px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Email</div>
    <div style="font-size:15px;line-height:1.8;color:#1a1a1a;background:#f9fafb;border:1px solid #e5e7eb;border-radius:6px;padding:18px">${emailBodyHtml}</div>
  </div>

  <div style="background:#fff;padding:14px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:5px">Personalization assessment</div>
    <span style="background:${pqColor}22;color:${pqColor};font-size:12px;font-weight:700;padding:3px 10px;border-radius:10px">${esc((e.personalization_quality||'?').replace(/_/g,' '))}</span>
    <div style="font-size:13px;color:#6b7280;margin-top:6px">${esc(e.personalization_quality_note)}</div>
  </div>

  ${researchItems ? `<div style="background:#fffbeb;padding:14px 26px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:8px">Research before sending</div>
    <ul style="padding-left:18px;margin:0">${researchItems}</ul>
  </div>` : ''}

  ${e.follow_up_angle ? `<div style="background:#f0fdf4;padding:12px 26px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:5px">Follow-up angle</div>
    <div style="font-size:14px;color:#166534;line-height:1.6">${esc(e.follow_up_angle)}</div>
  </div>` : ''}

  <div style="background:#111827;color:#4b5563;font-size:11px;padding:10px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Cold Email Personalizer · ${esc(m.prospectName)} · ${new Date().toLocaleDateString()}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, prospectName: m.prospectName, prospectCompany: m.prospectCompany, subjectLine: e.subject_line, personalizationQuality: e.personalization_quality, email: e } }];
